import React, { useRef, useState } from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import NewsStack from "components/newsStack";
import PrettyCalendar from "components/calendar";

import HeroImage from "assets/img/bg1.png";
import BannerImage from "assets/img/banniere.png";
import ressourcesImg from "assets/img/ressourcesImg.png";
import News1 from "assets/img/mbaye.png";
import News2 from "assets/img/newdeal.jpg";
import News3 from "assets/img/sim.jpg";

// Assets des sites (Noms de variables plus clairs)
import siteHeritage from "assets/img/heritage.png";
import siteAccel from "assets/img/accel.png";
import siteShirikia from "assets/img/shirikia.png";

import fatou from "assets/img/fatou.jpg";
import moussa from "assets/img/moussa.jpg";
import ndeye from "assets/img/ndeye.jpg";
import sankara from "assets/img/sankara.jpg";

// Icône du bouton flottant
import ChatbotIcon from "assets/img/alex.png";

const ProfileCard = ({ name, image, text, userTitle }) => (
  <div className="flex items-start gap-6 pb-6 mb-6 last:mb-0 last:pb-0 last:border-b-0 border-b border-[#d7d7da]">
    <div className="w-[120px] h-[120px] rounded-[18px] overflow-hidden shrink-0">
      <img src={image} alt={name} className="w-full h-full object-cover" />
    </div>
    <div className="ml-4">
      <div className="text-[#1c58c9] font-bold uppercase tracking-wide text-sm mb-1">
        {userTitle}
      </div>
      <p className="text-[15px] leading-relaxed">
        <span className="font-extrabold">{text.split('<br/>')[0]}</span><br />
        {text.split('<br/>').slice(1).join('<br/>')}
      </p>
    </div>
  </div>
);

export default function Index() {
  const [bannerOffset, setBannerOffset] = useState(0);
  const twoColRef = useRef(null);
  const [chatOpen, setChatOpen] = useState(false); // État d’ouverture du chatbot

  const frequentSites = [
    { title: "Site 1 - Baobab", description: "Le héro du projet...", image: siteHeritage },
    { title: "Site 2 - Data Map", description: "Plateforme donnée...", image: siteAccel },
    { title: "Site 3 - Shirikia", description: "Accélérateur...", image: siteShirikia },
  ];

  const profiles = [
    { name: "FATOU DIA", userTitle: "SEYNABOU NDOUR", image: fatou, text: "Lorem Ipsum is simply dummy<br/>text of the printing and<br/>typesetting industry." },
    { name: "MOUSSA FALL", userTitle: "MOUSSA TRAORE", image: moussa, text: "Lorem Ipsum is simply dummy<br/>text of the printing and<br/>typesetting industry." },
    { name: "NDEYE SENE", userTitle: "NDEYE SENE", image: ndeye, text: "Lorem Ipsum is simply dummy<br/>text of the printing and<br/>typesetting industry." },
  ];

  return (
    <>
      <IndexNavbar fixed />

      {/* HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour !
            </p>
          </div>
        </div>
      </section>

      {/* === Bouton flottant Chatbot (Z-INDEX AUGMENTÉ) === */}
      <button
        type="button"
        onClick={() => setChatOpen((v) => !v)}
        className="fixed bottom-6 right-6 **z-[90]** cursor-pointer group rounded-full shadow-lg border-2 border-white overflow-hidden"
        aria-label="Ouvrir le chatbot"
        title="Chat"
      >
        <div className="relative">
          <img
            src={ChatbotIcon}
            alt="Chatbot"
            className="w-16 h-16 object-cover group-hover:scale-110 transition-transform duration-300"
          />
          {/* Halo discret */}
          <span className="pointer-events-none absolute inset-0 rounded-full animate-ping bg-[#25509d]/30" />
        </div>
      </button>

      {/* === Panneau de Chat (Z-INDEX AUGMENTÉ) === */}
      <div
        className={`fixed right-6 **z-[100]** transition-all duration-300 ${chatOpen ? "bottom-24 opacity-100" : "bottom-8 opacity-0 pointer-events-none"
          }`}
        style={{ width: 360 }}
      >
        <div className="bg-white rounded-2xl shadow-2xl border border-blueGray-100 overflow-hidden">
          {/* En-tête */}
          <div className="bg-[#20264e] text-white px-4 py-3 flex items-center justify-between">
            <div className="font-semibold">Assistant</div>
            <button
              onClick={() => setChatOpen(false)}
              className="text-white/80 hover:text-white text-sm"
              aria-label="Fermer"
            >
              ✕
            </button>
          </div>
          {/* Corps (messages mock) */}
          <div className="h-64 p-4 space-y-3 bg-blueGray-50/40">
            <div className="text-sm text-blueGray-700">
              Bonjour 👋 Comment puis-je vous aider ?
            </div>
            {/* Bulles de démonstration */}
            <div className="max-w-[85%] rounded-xl bg-white shadow px-3 py-2 text-sm">
              Je peux vous guider sur la plateforme.
            </div>
          </div>
          {/* Saisie */}
          <div className="border-t border-blueGray-100 p-2 flex items-center gap-2">
            <input
              type="text"
              placeholder="Écrivez votre message…"
              className="flex-1 px-3 py-2 rounded-lg border border-blueGray-200 focus:outline-none focus:ring-2 focus:ring-[#25509d]"
            />
            <button className="px-3 py-2 rounded-lg bg-[#25509d] text-white text-sm hover:opacity-95">
              Envoyer
            </button>
          </div>
        </div>
      </div>

      {/* 2 colonnes : Calendrier + Actualités */}
      <section className="relative bg-white py-16">
        <div className="container mx-auto px-4">
          <div ref={twoColRef} className="flex flex-col md:flex-row items-start md:space-x-8 space-y-8 md:space-y-0">
            <div className="w-full md:w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Un jour spécial pour ?</h3>
              <PrettyCalendar
                initialYear={2023}
                initialMonth={2}
                selectedDay={20}
                events={[
                  { date: "2023-02-20", label: "Anniversaire de Ousmane DIA" },
                  { date: "2023-02-16", label: "Réunion Produits" },
                ]}
              />
            </div>

            <div className="w-full md:w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Actualités</h3>
              <NewsStack
                items={[
                  { img: News2, href: "#" },
                  { img: News3, href: "#" },
                  { img: News1, href: "#" },
                ]}
              />
            </div>
          </div>
        </div>
      </section>

      {/* Bannière */}
      <section className="relative w-full z-20" style={{ marginTop: "-500px" }}>
        <img
          src={BannerImage}
          alt="Bannière"
          className="w-full h-[500px] object-cover rounded-lg shadow-lg"
        />
      </section>

      {/* Image ressources */}
      <section className="relative w-full bg-white py-16">
        <div className="w-full">
          <img
            src={ressourcesImg}
            alt="Nouvelle section"
            className="rounded-lg shadow-lg object-cover"
            style={{
              width: "45%",
              height: "33%",
              marginLeft: "0",
              marginTop: "-350px",
            }}
          />
        </div>
      </section>

      {/* SITES FREQUENTS / BIENVENUE (Optimisé) */}
      <section className="w-full bg-white py-14">
        <div className="container mx-auto px-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
            {/* Colonne SITES FREQUENTS (1/3) */}
            <div className="col-span-1">
              <h2 className="text-[#2d4ea3] font-extrabold tracking-wide text-[24px] mb-6">
                SITES FREQUENTS
              </h2>
              <div className="space-y-8">
                {frequentSites.map((site, i) => (
                  <div
                    key={i}
                    className="w-full h-[120px] rounded-[18px] border-[4px] border-[#2f5ac8] overflow-hidden shadow-[0_6px_18px_rgba(0,0,0,0.08)]"
                  >
                    <img src={site.image} alt={`Site ${i + 1}`} className="w-full h-full object-cover" />
                  </div>
                ))}
              </div>
            </div>

            {/* Colonne BIENVENUE (2/3) */}
            <div className="md:col-span-2">
              <h2 className="text-[#2d4ea3] font-extrabold tracking-wide text-[28px] mb-6 text-right">
                BIENVENUE !
              </h2>

              <div className="bg-[#e5e5e7] rounded-[22px] p-8 shadow-xl">
                <div className="space-y-6">
                  {profiles.map((profile, index) => (
                    <ProfileCard
                      key={index}
                      {...profile}
                      userTitle={profile.userTitle} // Correction : l'utilisation de userTitle est maintenant dynamique
                      text={profile.text}
                    />
                  ))}
                </div>
              </div>
            </div>
            {/* fin col bienvenue */}
          </div>
        </div>
      </section>

      {/* Citation */}
      <section className="w-full bg-white py-20 flex justify-center items-center">
        <div className="flex flex-col md:flex-row items-center justify-center gap-8 md:gap-10">
          <div className="flex flex-col items-center md:items-start text-center md:text-left">
            <div className="w-[130px] h-[130px] md:w-[150px] md:h-[150px] rounded-lg overflow-hidden shadow">
              <img src={sankara} alt="Thomas Sankara" className="w-full h-full object-cover" />
            </div>
            <span className="mt-3 text-base md:text-lg font-semibold">Thomas Sankara</span>
          </div>

          <div className="bg-[#e6e6e6] rounded-md md:rounded-lg shadow-sm px-6 py-5 md:px-8 md:py-6 max-w-[600px]">
            <p className="font-semibold italic text-[#2b2b2b] text-[15px] md:text-[17px] leading-relaxed text-center">
              “Nous devons accepter de vivre africain. C’est la seule façon de vivre
              libre et de vivre digne.”
            </p>
          </div>
        </div>
      </section>

      <Footer />
    </>
  );
}
